/* Service Requests: current Figma screens, backed by the connected model. */
function serviceFilterButton(){return button(img('44121.svg')+'Filters'+img('f273c.svg'),'design-request-filter','service-filter');}
function serviceBadge(status){return '<span class="service-badge '+(['Declined','In review','Needs follow-up'].includes(status)?'warning':'')+'">'+(status==='Needs follow-up'?img('8f8b7.svg'):'')+esc(status)+'</span>';}
function serviceTime(value){return value?new Date(value).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}):'—';}
function servicePageLabel(page){return ({overview:'Overview',rooms:'Rooms',guests:'Guests',billing:'Invoices',documents:'Documents',schedule:'Schedule',invite:'Invite guests',stay:'My stay',room:'Room',payment:'Payment',charges:'Charges',extras:'Add-ons'})[page]||page;}
function servicePeople(){return [...new Map(mailboxPeople().map(p=>[p.email,p])).values()];}
function serviceGuests(){return [...pickup().reservations,...roomSlots().filter(s=>s.guest&&s.payer==='Organizer').map(organizerPaidGuest)].filter(r=>r.paid&&!r.checkedOut);}
const serviceModelRequest=requestService,serviceModelResolve=resolveService;
requestService=function(id,r=portalGuest()){const q=serviceModelRequest(id,r);q.createdAt=new Date().toISOString();q.assigned='Unassigned';if(state.ui.app==='guest'){const logs=ops().portalActivity??={},a=logs[r.guest.email]??={pages:[]};a.lastAction='Requested '+q.title;}save();return q;};
resolveService=function(id,status,message,assigned){serviceModelResolve(id,status,message,assigned);const q=ops().requests.find(x=>x.id===id);q.resolvedAt=new Date().toISOString();if(message?.trim())q.message=message.trim();save();};
serviceRequestList=function(){const p=ops(),items=p.requests.filter(q=>!p.requestFilter||p.requestFilter==='All'||q.status===p.requestFilter),rows=items.map(q=>[esc(q.title),button(v2Full(q.guest),'cx-contact-'+q.guestKey,'link'),button('#'+q.reservationId,'v2-record-'+q.reservationId,'link'),esc(q.when),esc(serviceById(q.serviceId)?.category||'Request'),serviceBadge(q.status),esc(q.assigned||'Unassigned'),button(q.status==='New'?'Review':'View','cx-request-'+q.id,'link')]);let content=table(['REQUEST','GUEST','RESERVATION','WHEN','TYPE','STATUS','ASSIGNED TO',''],rows,'service-requests');if(items[0]?.status==='New')content=content.replace('<tbody><tr>','<tbody><tr class="new-row">');if(!items.length)content=content.replace('<tbody></tbody>','<tbody><tr><td colspan="8" class="service-empty">No requests found.</td></tr></tbody>');return '<div class="admin service-admin service-current">'+sfNav()+adminHeader('Request Manager','Open requests','',serviceFilterButton()+button(img('eb609.svg')+'New request','service-new','primary'))+'<div class="admin-main"><section class="service-request-table">'+content+'</section></div></div>';};
serviceRequestDetail=function(){const q=ops().requests.find(q=>q.id===ops().currentRequest)||ops().requests[0];if(!q)return serviceRequestList();const s=serviceById(q.serviceId),handled=q.status!=='New';const timeline=[...(handled?[['Request '+q.status.toLowerCase(),serviceTime(q.resolvedAt)+' · '+ops().staff+' · '+v2Full(q.guest)+' notified']]:[]),...(q.assigned&&q.assigned!=='Unassigned'?[['Assigned to '+q.assigned,serviceTime(q.resolvedAt||q.createdAt)]]:[]),['Request received',serviceTime(q.createdAt)+' · Guest portal']].map(([title,sub])=>'<div class="service-event">'+img('b5b45.svg')+'<div><b>'+esc(title)+'</b><small>'+esc(sub)+'</small></div></div>').join('');return '<div class="admin service-admin service-current service-detail">'+sfNav()+'<header class="service-detail-heading"><div><small>Request '+esc(q.id)+'</small><div class="row"><h1>'+esc(q.title)+'</h1>'+serviceBadge(q.status)+'</div><p>Requested in the '+(q.source==='Staff'?'admin portal':'guest portal')+' · '+serviceTime(q.createdAt)+'</p></div><div class="row">'+button('Back to requests','cx-requests')+(handled?button('Message guest','cx-service-message'):'')+'</div></header><div class="admin-main request-layout"><div class="stack">'+panel('Request details','<div class="grid2">'+detail('Guest',button(v2Full(q.guest),'cx-contact-'+q.guestKey,'link'))+detail('Activity',esc(q.title))+detail('Reservation',button('#'+q.reservationId+' · Room '+q.unit,'v2-record-'+q.reservationId,'link'))+detail('Date and time',esc(q.when))+detail('Group',esc(state.request.organization))+detail('Guests / price','1 guest · '+(q.amount?money(q.amount):'Included in the group booking'))+'</div>')+panel('Activity',timeline)+'</div><div class="stack">'+panel(handled?'Handled':'Next step','<form id="cx-service-form" class="service-form">'+select('Assigned to','assigned',q.assigned&&q.assigned!=='Unassigned'?q.assigned:'Alex Rivera',['Unassigned','Alex Rivera','Sam Patel','Jordan Reyes','Chef team'])+textarea('Message to the guest','message',q.message||(q.serviceId==='forest'?'Meet at the Main Lodge Lobby at 8:50 AM.':q.title+' is confirmed for '+q.when+'.'))+(handled?serviceBadge('Guest notified'):'<div class="service-decision">'+button('Confirm request','cx-service-confirm','primary')+button('Decline','cx-service-decline')+'</div>')+'</form>')+panel('Capacity','<p>'+esc(s.title)+' · '+esc(s.when)+'</p><h3>'+(s.booked+ops().requests.filter(x=>x.serviceId===s.id&&x.status==='Confirmed').length)+' of '+s.capacity+' spots booked</h3>')+'</div></div></div>';};
function servicePortalRows(){const activity=ops().portalActivity||{};return servicePeople().map(p=>{const a=activity[p.email]||{},requests=ops().requests.filter(q=>q.guest.email===p.email);return {...p,...a,requests,status:a.openedAt?'Opened':'Needs follow-up'};});}
function servicePortalActivity(){let people=servicePortalRows();const all=people,opened=people.filter(p=>p.openedAt),latest=opened.map(p=>p.openedAt).sort().at(-1);if(ops().portalFilter==='Opened')people=opened;if(ops().portalFilter==='Needs follow-up')people=people.filter(p=>!p.openedAt);const stats=[['Secure links sent',all.length,all.filter(p=>p.role==='Organizer').length+' organizer · '+all.filter(p=>p.role==='Guest').length+' guests'],['Opened',opened.length,(all.length?Math.round(opened.length/all.length*100):0)+'% of links'],['Requests from guests',ops().requests.length,'from '+new Set(ops().requests.map(q=>q.guest.email)).size+ (new Set(ops().requests.map(q=>q.guest.email)).size===1?' guest':' guests')],['Last opened',latest?Math.max(0,Math.floor((Date.now()-new Date(latest).getTime())/60000))+' min ago':'—',all.find(p=>p.openedAt===latest)?.name||'No links opened yet']];return '<div class="admin service-admin service-current">'+sfNav()+adminHeader('Group Block GBR-008','Portal activity','',serviceFilterButton()+button('Export','service-export')+button('Resend links','service-resend','primary')).replace(/<img[^>]+class="icon"[^>]*>/,'')+'<div class="admin-main"><div class="service-stats">'+stats.map(([label,value,sub])=>'<section><b>'+label+'</b><strong>'+value+'</strong><small>'+esc(sub)+'</small></section>').join('')+'</div><section class="service-request-table">'+table(['PERSON','ROLE','LINK SENT','LAST OPENED','PAGES VIEWED','ACTIONS','STATUS'],people.map(p=>[esc(p.name),p.role,p.sentAt?serviceTime(p.sentAt):'Secure link',p.openedAt?serviceTime(p.openedAt):'Never opened',esc((p.pages||[]).map(servicePageLabel).join(', ')||'—'),esc(p.lastAction||(p.requests.length?p.requests.length+' service requests':'—')),serviceBadge(p.status)]),'service-activity-table')+'</section></div></div>';}
const serviceDesignRender=render,serviceDesignHandle=handle,serviceDesignOverlay=renderOverlay;
render=function(){if(state.ui.app==='guest'&&['organizer-portal','guest-portal','service-sent'].includes(state.ui.guest)){const person=state.ui.portalRole==='organizer'?{email:state.request.email}:portalGuest()?.guest;if(person?.email){const logs=ops().portalActivity??={},a=logs[person.email]??={pages:[]};a.openedAt=new Date().toISOString();const page=state.ui.guest==='service-sent'?'Request sent':state.ui.portalPage||'overview';if(!a.pages.includes(page))a.pages.push(page);save();}}if(state.ui.app==='admin'&&state.ui.admin==='service-activity'){$('#demo').innerHTML=demoBar();$('#app').innerHTML=servicePortalActivity();renderOverlay();return;}return serviceDesignRender();};
handle=function(a,el){if(a==='service-activity')return navigate('admin','service-activity');if(a==='service-new'){openModal('service-new');return;}if(a==='service-new-save'){const f=document.querySelector('#service-new-form');if(!f.reportValidity())return;const v=formValues('#service-new-form'),r=serviceGuests().find(r=>guestKey(r)===v.guest);const q=requestService(v.service,r);q.source='Staff';ops().currentRequest=q.id;modal=null;navigate('admin','service-detail');toast('Request created.');return;}if(a==='design-apply-filter'){const view=document.querySelector('[name="service-view"]').value,filter=document.querySelector('[name="design-request-filter"]').value;if(view==='Portal activity')ops().portalFilter=filter;else ops().requestFilter=filter;modal=null;save();return navigate('admin',view==='Portal activity'?'service-activity':'service-list');}if(a==='service-export'){const csv=x=>'"'+String(x??'').replaceAll('"','""')+'"';downloadBlob([['Person','Role','Last opened','Pages viewed','Status'],...servicePortalRows().map(p=>[p.name,p.role,p.openedAt||'',(p.pages||[]).map(servicePageLabel).join(', '),p.status])].map(row=>row.map(csv).join(',')).join('\r\n'),'text/csv','Portal_activity_GBR-008.csv');return;}if(a==='service-resend'){openModal('service-resend');return;}if(a==='service-resend-save'){const logs=ops().portalActivity??={};servicePortalRows().filter(p=>!p.openedAt).forEach(p=>{(logs[p.email]??={pages:[]}).sentAt=new Date().toISOString();const slot=roomSlots().find(s=>s.guest?.email===p.email);if(slot)slot.invited=true;});modal=null;save();render();toast('Secure links resent.');return;}const person=state.ui.app==='guest'?(state.ui.portalRole==='organizer'?{email:state.request?.email}:portalGuest()?.guest):null;const result=serviceDesignHandle(a,el);const label=({'cx-meals-save':'Updated meal counts','v2-send-invites':'Sent guest invitations','download-beo':'Downloaded BEO','download-contract':'Downloaded contract','portal-download':'Downloaded receipt','doc-beo':'Viewed BEO','doc-contract':'Viewed contract','cx-guest-pay':'Opened balance payment','portal-copy-code':'Copied group code'})[a];if(person?.email&&label){const logs=ops().portalActivity??={},entry=logs[person.email]??={pages:[]};entry.lastAction=label;save();}return result;};
renderOverlay=function(){if(!['design-request-filter','service-new','service-resend'].includes(modal))return serviceDesignOverlay();let title,body,footer;if(modal==='design-request-filter'){title='Filters';const activity=state.ui.admin==='service-activity';body=select('View','service-view',activity?'Portal activity':'Requests',['Requests','Portal activity'])+select('Status','design-request-filter',(activity?ops().portalFilter:ops().requestFilter)||'All',['All','New','Confirmed','Declined','Opened','Needs follow-up']);footer=button('Apply','design-apply-filter','primary');}else if(modal==='service-new'){title='New request';const guests=serviceGuests();body='<form id="service-new-form" class="stack"><label>Guest<select name="guest" required>'+guests.map(r=>'<option value="'+esc(guestKey(r))+'">'+esc(v2Full(r.guest))+' · #'+r.id+'</option>').join('')+'</select></label><label>Service<select name="service" required>'+serviceCatalog.map(s=>'<option value="'+s.id+'">'+esc(s.title)+'</option>').join('')+'</select></label></form>';footer=button('Create request','service-new-save','primary',!guests.length);}else{title='Resend secure links';const people=servicePortalRows().filter(p=>!p.openedAt);body='<p>Resend to '+people.length+' people who have not opened their link.</p>'+people.map(p=>'<p class="mt">'+esc(p.name)+' · '+esc(p.email)+'</p>').join('');footer=button('Resend links','service-resend-save','primary',!people.length);}document.body.style.overflow='hidden';$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal small" role="dialog" aria-modal="true" aria-labelledby="service-modal-title"><button class="modal-close" data-action="close-modal" aria-label="Close">×</button><header class="modal-header" id="service-modal-title">'+title+'</header><div class="modal-content stack">'+body+'</div><footer class="modal-footer">'+button('Cancel','close-modal')+footer+'</footer></section></div>';};
render();
